exports.init = (params, rng) => {
  const n = params.nBirds ?? params.n_birds ?? 500;
  const xs = new Array(n), ys = new Array(n), vxs = new Array(n), vys = new Array(n);
  for (let i=0;i<n;i++) {
    xs[i] = rng.range(40,60);
    ys[i] = rng.range(40,60);
    const ang = rng.range(0, 6.283185307179586);
    const sp = rng.range(0.8, 1.6);
    vxs[i] = Math.cos(ang)*sp;
    vys[i] = Math.sin(ang)*sp;
  }
  return {xs, ys, vxs, vys, t:0};
};

exports.step = (state, params, rng) => {
  const xs = state.xs, ys = state.ys, vxs = state.vxs, vys = state.vys;
  const n = xs.length;
  const pr = Math.max(1, params.perceptionRadius ?? params.perception_radius ?? 10);
  const sepW = params.separationWeight ?? params.separation_weight ?? 1.5;
  const aliW = params.alignmentWeight ?? params.alignment_weight ?? 1;
  const cohW = params.cohesionWeight ?? params.cohesion_weight ?? 1;
  const noise = params.noise ?? 0.05;
  const maxSpeed = Math.max(0.2, params.maxSpeed ?? params.max_speed ?? 2);
  const sepR = 2.8;
  let gcx = 0, gcy = 0;
  for (let i = 0; i < n; i++) { gcx += xs[i]; gcy += ys[i]; }
  gcx /= n; gcy /= n;
  const cell = pr;
  const buckets = new Map();
  const keyOf = (x, y) => (Math.floor(x / cell) + "," + Math.floor(y / cell));
  for (let i = 0; i < n; i++) {
    const k = keyOf(xs[i], ys[i]);
    const list = buckets.get(k);
    if (list) list.push(i);
    else buckets.set(k, [i]);
  }
  const nxs = new Array(n), nys = new Array(n), nvx = new Array(n), nvy = new Array(n);
  for (let i = 0; i < n; i++) {
    let sx = 0, sy = 0, sc = 0, ax = 0, ay = 0, ac = 0, cx = 0, cy = 0, cc = 0;
    let nearD = 1e9, ndx = 0, ndy = 0;
    const gx = Math.floor(xs[i] / cell), gy = Math.floor(ys[i] / cell);
    for (let oy = -1; oy <= 1; oy++) {
      for (let ox = -1; ox <= 1; ox++) {
        const list = buckets.get((gx + ox) + "," + (gy + oy));
        if (!list) continue;
        for (let k = 0; k < list.length; k++) {
          const j = list[k];
          if (j === i) continue;
          const dx = xs[j] - xs[i], dy = ys[j] - ys[i];
          const d2 = dx * dx + dy * dy;
          if (d2 > pr * pr || d2 < 1e-6) continue;
          const d = Math.sqrt(d2);
          cc++; cx += xs[j]; cy += ys[j];
          ac++; ax += vxs[j]; ay += vys[j];
          if (d < nearD) { nearD = d; ndx = dx; ndy = dy; }
          if (d < sepR) {
            const push = (sepR - d) / d;
            sc++; sx -= (dx / d) * push; sy -= (dy / d) * push;
          }
        }
      }
    }
    let vx = vxs[i], vy = vys[i];
    if (ac > 0 && aliW > 0) { vx += ((ax / ac) - vx) * 0.35 * aliW; vy += ((ay / ac) - vy) * 0.35 * aliW; }
    if (noise > 0) { vx += (rng.next() - 0.5) * noise; vy += (rng.next() - 0.5) * noise; }
    const sp = Math.hypot(vx, vy);
    if (sp > maxSpeed) { vx = vx / sp * maxSpeed; vy = vy / sp * maxSpeed; }
    else if (sp < 0.25) { const a = rng.range(0, 6.283185307179586); vx += Math.cos(a) * 0.35; vy += Math.sin(a) * 0.35; }
    let px = xs[i] + vx, py = ys[i] + vy;
    if (cohW > 0) {
      const gdx = gcx - xs[i], gdy = gcy - ys[i];
      const gd = Math.hypot(gdx, gdy);
      if (gd > 22) { px += (gdx / gd) * 0.35 * cohW; py += (gdy / gd) * 0.35 * cohW; }
    }
    if (sepW > 0 && nearD < sepR && nearD > 1e-6) {
      const nx = ndx / nearD, ny = ndy / nearD;
      const shove = (sepR - nearD) * 0.18 * Math.min(sepW, 2);
      px -= nx * shove; py -= ny * shove;
    }
    nxs[i] = px; nys[i] = py; nvx[i] = vx; nvy[i] = vy;
  }
  if (sepW > 0) {
    const minDist = 1.6;
    for (let sweep = 0; sweep < 5; sweep++) {
      const relax = new Map();
      const rkey = (x, y) => (Math.floor(x / minDist) + "," + Math.floor(y / minDist));
      for (let i = 0; i < n; i++) {
        const k = rkey(nxs[i], nys[i]);
        const list = relax.get(k);
        if (list) list.push(i); else relax.set(k, [i]);
      }
      for (let i = 0; i < n; i++) {
        const gx = Math.floor(nxs[i] / minDist), gy = Math.floor(nys[i] / minDist);
        let best = 1e9, bx = 0, by = 0;
        for (let oy = -1; oy <= 1; oy++) {
          for (let ox = -1; ox <= 1; ox++) {
            const list = relax.get((gx + ox) + "," + (gy + oy));
            if (!list) continue;
            for (let k = 0; k < list.length; k++) {
              const j = list[k];
              if (j === i) continue;
              const dx = nxs[j] - nxs[i], dy = nys[j] - nys[i];
              const d2 = dx * dx + dy * dy;
              if (d2 < best && d2 > 1e-8) { best = d2; bx = dx; by = dy; }
            }
          }
        }
        const d = Math.sqrt(best);
        if (d < minDist) { nxs[i] -= (bx / d) * (minDist - d); nys[i] -= (by / d) * (minDist - d); }
      }
    }
  }
  state.xs = nxs; state.ys = nys; state.vxs = nvx; state.vys = nvy;
  state.t = (state.t || 0) + 1;
  return state;
};
exports.observe = (state) => {
  const xs = state.xs, ys = state.ys, vxs = state.vxs, vys = state.vys;
  const n = xs.length || 1;
  let mx = 0, my = 0, cx = 0, cy = 0;
  for (let i = 0; i < xs.length; i++) {
    const sp = Math.hypot(vxs[i], vys[i]) || 1;
    mx += vxs[i] / sp; my += vys[i] / sp;
    cx += xs[i]; cy += ys[i];
  }
  cx /= n; cy /= n;
  const polarization = Math.hypot(mx, my) / n;
  let radius = 0;
  for (let i = 0; i < xs.length; i++) radius += Math.hypot(xs[i] - cx, ys[i] - cy);
  radius /= n;
  const hit = 1.35;
  const buckets = new Map();
  const keyOf = (x, y) => (Math.floor(x / hit) + "," + Math.floor(y / hit));
  for (let i = 0; i < xs.length; i++) {
    const k = keyOf(xs[i], ys[i]);
    const list = buckets.get(k);
    if (list) list.push(i); else buckets.set(k, [i]);
  }
  let bumping = 0;
  for (let i = 0; i < xs.length; i++) {
    const gx = Math.floor(xs[i] / hit), gy = Math.floor(ys[i] / hit);
    let hitOne = false;
    for (let oy = -1; oy <= 1 && !hitOne; oy++) {
      for (let ox = -1; ox <= 1 && !hitOne; ox++) {
        const list = buckets.get((gx + ox) + "," + (gy + oy));
        if (!list) continue;
        for (let k = 0; k < list.length; k++) {
          const j = list[k];
          if (j === i) continue;
          const dx = xs[j] - xs[i], dy = ys[j] - ys[i];
          if (dx * dx + dy * dy < hit * hit) { hitOne = true; break; }
        }
      }
    }
    if (hitOne) bumping++;
  }
  return { collision_rate: bumping / n, polarization, flock_radius: radius };
};
exports.view = (state, params) => {
  const xs = state.xs, ys = state.ys, vxs = state.vxs, vys = state.vys;
  const n = xs.length;
  let cx = 0, cy = 0;
  for (let i=0;i<n;i++) { cx += xs[i]; cy += ys[i]; }
  cx /= n; cy /= n;
  let sum = 0;
  for (let i=0;i<n;i++) { const dx = xs[i]-cx, dy = ys[i]-cy; sum += Math.sqrt(dx*dx+dy*dy); }
  const meanR = sum / n;
  const span = Math.max(40, meanR * 3.2);
  const agents = new Array(n);
  for (let i=0;i<n;i++) {
    const x = (xs[i]-cx)/span+0.5;
    const y = (ys[i]-cy)/span+0.5;
    const xv = x<0?0:x>1?1:x;
    const yv = y<0?0:y>1?1:y;
    const heading = Math.atan2(vys[i], vxs[i]);
    agents[i] = {id:'b'+i, x:xv, y:yv, tint:0.82, heading, sprite:'starling'};
  }
  return {kind:'population', agents};
};
